import json
from typing import Optional, List, Dict, ClassVar  # noqa: F401

from taf.cloud.cbam.vnf.vnf import VNF, SupportedVnfSchemas
from taf.cloud.cbam import exception

from taf.cloud.cbam.schemas.v3.vim_info import VimInfo, VimInfo3_3
from taf.cloud.cbam.schemas.v3.operation_execution import OperationExecution


class SupportedVnf3Schemas(SupportedVnfSchemas):
    VimInfo = VimInfo  # type: ClassVar
    OperationExecution = OperationExecution  # type: ClassVar

    def __init__(self, api_version):
        if api_version == "3.3":
            self.VimInfo = VimInfo3_3
        else:
            self.VimInfo = VimInfo


class VNF3(VNF):
    DEFAULT_INSTANTIATE_API_VERSION = '3.1'
    DEFAULT_PUT_VIM_INFO_API_VERSION = '3.1'
    supported_schemas = SupportedVnf3Schemas(api_version=DEFAULT_INSTANTIATE_API_VERSION)

    def __init__(self, session, api_version=None):
        self._session = session
        self._api_version = api_version
        if self._api_version is not None:
            self.supported_schemas = SupportedVnf3Schemas(api_version=self._api_version)

    def _to_endpoint(self,
                     method,
                     url,
                     api_version=None,
                     **content):
        if api_version is None:
            api_version = self._api_version

        response = self._session.send_request(
            method=method,
            endpoint=url,
            api_version=api_version,
            **content)
        return response

    def create(self, vnf_info):
        # type: (SupportedVnf3Schemas.VnfInfo) -> SupportedVnf3Schemas.VnfInfo
        body = {'vnfdId': vnf_info.vnfd_id,
                'name': vnf_info.name,
                'description': vnf_info.description}
        response = self._to_endpoint(method='post',
                                     url='vnfm/lcm/v3/vnfs',
                                     data=json.dumps(body))
        response = response.convert(success_class=self.supported_schemas.VnfInfo,
                                    fail_class=self.supported_schemas.ProblemDetails,
                                    success_codes=[201])
        return response

    def query_all_vnfs(self):
        # type: () -> List[SupportedVnf3Schemas.VnfInfo]
        response = self._to_endpoint(
            method='get', url='vnfm/lcm/v3/vnfs')
        result = response.convert_list(
            success_codes=[200],
            success_class=self.supported_schemas.VnfInfo,
            fail_class=self.supported_schemas.ProblemDetails)

        return result

    def query_one(self, vnf_info):
        # type: (SupportedVnf3Schemas.VnfInfo) -> SupportedVnf3Schemas.VnfInfo
        endpoint = 'vnfm/lcm/v3/vnfs/{_id}'.format(_id=vnf_info.id)
        response = self._to_endpoint(
            method='get',
            url=endpoint)
        result = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.VnfInfo,
            success_codes=[200])

        return result

    def get_vim_info(self, vnf_info, vim_info):
        # type: (SupportedVnf3Schemas.VnfInfo, SupportedVnf3Schemas.VimInfo) -> SupportedVnf3Schemas.VimInfo
        vnf_instance_id = self._get_vnf_id_by_name(vnf_info.name)
        endpoint = 'vnfm/lcm/v3/vnfs/{vnfInstanceId}/vim_info/{vimId}'.format(
            vnfInstanceId=vnf_instance_id, vimId=vim_info.id)

        response = self._to_endpoint(method='get', url=endpoint)
        response = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.VimInfo,
            success_codes=[200])
        return response

    def put_vim_info(self,
                     vnf_info,  # type: SupportedVnf3Schemas.VnfInfo
                     vim_info,  # type: SupportedVnf3Schemas.VimInfo
                     interface_info,  # type: dict
                     **kwargs  # type: Optional[dict]
                     ):

        body = {'accessInfo': kwargs, 'id': vim_info.id,
                'interfaceInfo': {'endpoint': interface_info},
                'vimInfoType': vim_info.vim_info_type}

        vnf_instance_id = self._get_vnf_id_by_name(vnf_info.name)
        endpoint = 'vnfm/lcm/v3/vnfs/{vnfInstanceId}/vim_info/{vimId}'.format(
            vnfInstanceId=vnf_instance_id, vimId=vim_info.id)

        response = self._to_endpoint(
            method='put', url=endpoint,
            api_version=self.DEFAULT_PUT_VIM_INFO_API_VERSION,
            data=json.dumps(body))

        response = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.VimInfo,
            success_codes=[200])
        return response

    def instantiate(self, name, body_content, password, flavour_id=None):
        vnf_id = self._get_vnf_id_by_name(name)
        body = self._create_instantiate_request_body(body_content, password,
                                                     flavour_id)
        endpoint = 'vnfm/lcm/v3/vnfs/{}/instantiate'.format(vnf_id)
        response = self._to_endpoint(
            method='post', url=endpoint,
            data=body, api_version=self.DEFAULT_INSTANTIATE_API_VERSION)
        response = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.OperationExecution,
            success_codes=[202])
        return response

    def _create_instantiate_request_body(self,
                                         body,
                                         password,
                                         flavour_id=None):
        if flavour_id is not None:
            body['flavourId'] = flavour_id
        if 'apiVersion' in body:
            del body['apiVersion']
        body['vims'][0]['accessInfo']['password'] = password
        return json.dumps(body)

    def modify(self, name, parameters_to_change):
        vnf_id = self._get_vnf_id_by_name(name)
        endpoint = 'vnfm/lcm/v3/vnfs/{}'.format(vnf_id)

        response = self._to_endpoint(method='patch',
                                     url=endpoint,
                                     data=parameters_to_change)
        response = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.OperationExecution,
            success_codes=[202])
        return response

    def terminate(self,
                  name,
                  termination_type='GRACEFUL',
                  graceful_termination_timeout=None):
        vnf_id = self._get_vnf_id_by_name(name)
        body = self._create_terminate_request_body(
            termination_type, graceful_termination_timeout)
        endpoint = 'vnfm/lcm/v3/vnfs/{}/terminate'.format(vnf_id)

        response = self._to_endpoint(method='post',
                                     url=endpoint,
                                     data=json.dumps(body))
        response = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.OperationExecution,
            success_codes=[202])
        return response

    @staticmethod
    def _create_terminate_request_body(termination_type,
                                       graceful_termination_timeout):
        body = {'terminationType': termination_type}
        if graceful_termination_timeout is not None:
            body.update(
                {'gracefulTerminationTimeout': graceful_termination_timeout})
        return body

    def delete_vnf(self, vnf_info):
        vnf_id = self._get_vnf_id_by_name(vnf_info.name)
        endpoint = 'vnfm/lcm/v3/vnfs/{}'.format(vnf_id)

        response = self._to_endpoint(method='delete',
                                     url=endpoint)
        if response.status_code == 204:
            return
        else:
            return self.supported_schemas.ProblemDetails.from_response_dict(response.data)

    def upgrade(self, name, vnfd_id):
        vnf_id = self._get_vnf_id_by_name(name)
        endpoint = 'vnfm/lcm/v3/vnfs/{vnfInstanceId}/upgrade'.format(vnfInstanceId=vnf_id)
        body = {'vnfdId': vnfd_id}

        response = self._to_endpoint(
            method='post',
            url=endpoint,
            data=json.dumps(body))
        response = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.OperationExecution,
            success_codes=[202])
        return response

    def get_operation_execution_info(self, operation_execution):
        # type: (OperationExecution) -> SupportedVnfSchemas.ProblemDetails
        endpoint = 'vnfm/lcm/v3/operation_executions/{operationExecutionId}'.format(
            operationExecutionId=operation_execution.operation_id)

        response = self._to_endpoint(method='get', url=endpoint)
        response = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.OperationExecution,
            success_codes=[200, 202])
        return response

    def post_custom_operation(self, vnf_info, custom_operation_name, additional_params=None):
        # type: (SupportedVnf3Schemas.VnfInfo, str, Optional[Dict]) -> SupportedVnf3Schemas.OperationExecution
        vnf_instance_id = self._get_vnf_id_by_name(vnf_info.name)
        endpoint = 'vnfm/lcm/v3/vnfs/{vnfInstanceId}/custom/{customOperationName}'.format(
            vnfInstanceId=vnf_instance_id, customOperationName=custom_operation_name)

        if additional_params:
            body = {'additionalParams': additional_params}
            response = self._to_endpoint(method='post', url=endpoint, data=json.dumps(body))
        else:
            response = self._to_endpoint(method='post', url=endpoint)
        response = response.convert(
            fail_class=self.supported_schemas.ProblemDetails,
            success_class=self.supported_schemas.OperationExecution,
            success_codes=[202])
        return response

    def _get_vnf_id_by_name(self, name):
        vnfs_info = self.query_all_vnfs()

        if isinstance(vnfs_info, self.supported_schemas.ProblemDetails):
            problem_details = vnfs_info
            detail = problem_details.detail
            status = problem_details.status
            problem_message = 'Details: {}\nStatus: {}'.format(detail, status)

            exc_msg = "An error occured while querying VNFs: {}"
            exc_msg = exc_msg.format(problem_message)

            raise exception.VnfNameNotFoundException(exc_msg)

        for vnf in vnfs_info:
            if vnf.name == name:
                return vnf.id

        raise exception.VnfNameNotFoundException(name)
